<?php
declare(strict_types=1);
define('BASEPATH',__DIR__);
require __DIR__.'/header_storage.php';
require_once __DIR__.'/../../application/services/NativeCompanySearch.php';
$db->query('CREATE TABLE tblitemable(id INTEGER PRIMARY KEY,rel_id INTEGER,rel_type TEXT,description TEXT,long_description TEXT)');
$db->query('CREATE TABLE tblinvoices(id INTEGER PRIMARY KEY,issuer_id INTEGER,number TEXT,clientid INTEGER)');
$db->query('CREATE TABLE tblissuers_invoice_documents(invoice_id INTEGER,issuer_id INTEGER,formatted_number TEXT)');
$db->query("INSERT INTO tblinvoices VALUES(1,2,'101',100),(2,3,'102',200),(3,2,'103',100)");
$db->query("INSERT INTO tblissuers_invoice_documents VALUES(1,2,'INV-needle-A'),(2,3,'INV-needle-B'),(3,2,'INV-percent%literal')");
$db->query("INSERT INTO tblissuers_resource_permissions VALUES(2,18,'invoices','view'),(3,18,'invoices','view')");
$db->query('CREATE TABLE tblclients(userid INTEGER PRIMARY KEY,company TEXT,active INTEGER)');$db->query("INSERT INTO tblclients VALUES(100,'Historical primary',1),(200,'Private B',1)");$db->query('CREATE TABLE tblissuers_clients(client_id INTEGER,owner_issuer_id INTEGER)');$db->query('INSERT INTO tblissuers_clients VALUES(200,3)');
$search=new NativeCompanySearch($db,'tbl');$a=$search->search(2,18,'needle');$b=$search->search(3,18,'needle');hc(count($a)===1&&count($a[0]['result'])===1&&$a[0]['result'][0]['source_id']===1,'A only');hc(count($b)===1&&count($b[0]['result'])===1&&$b[0]['result'][0]['source_id']===2,'B only');
$r=$search->search(2,18,'%literal');hc(count($r[0]['result'])===1&&$r[0]['result'][0]['source_id']===3,'wildcard literal escaped');
$db->query("INSERT INTO tblinvoices VALUES(4,NULL,'needleLegacy',100)");hc(count($search->search(2,18,'needle')[0]['result'])===2,'primary union historical invoices');hc(count($search->search(3,18,'needle')[0]['result'])===1,'named excludes historical invoices');
$db->query('CREATE TABLE tblcompany_projects(id INTEGER PRIMARY KEY,issuer_id INTEGER,name TEXT)');$db->query('CREATE TABLE tblprojects(id INTEGER PRIMARY KEY,clientid INTEGER,name TEXT)');
$db->query("INSERT INTO tblprojects VALUES(1,100,'needle public legacy'),(2,200,'needle private B')");$db->query("INSERT INTO tblcompany_projects VALUES(1,2,'needle owned A'),(2,3,'needle owned B')");$db->query("INSERT INTO tblissuers_resource_permissions VALUES(2,18,'projects','view'),(3,18,'projects','view')");
$groups=$search->search(2,18,'needle');$project=array_values(array_filter($groups,fn($g)=>$g['type']==='projects'))[0];hc(count($project['result'])===2,'primary owned plus authorized legacy project');foreach($project['result'] as $r)hc($r['label']!=='needle private B','legacy relation B excluded before result');
$db->query("INSERT INTO tblitemable VALUES(1,1,'invoice','line%literal A','details'),(2,2,'invoice','line%literal B','private details'),(3,4,'invoice','line%literal historical','old')");
$lineA=array_values(array_filter($search->search(2,18,'line%literal'),fn($g)=>$g['type']==='invoice_items'))[0]['result'];
$lineB=array_values(array_filter($search->search(3,18,'line%literal'),fn($g)=>$g['type']==='invoice_items'))[0]['result'];
hc(count($lineA)===2&&$lineA[0]['secondary_label']==='line%literal A'&&$lineA[0]['label']==='INV-needle-A','owned invoice line uses frozen number and excludes B');
hc(count($lineB)===1&&$lineB[0]['secondary_label']==='line%literal B','B invoice items do not include A or primary history');
$db->query('CREATE TABLE tblcompany_sales_documents(id INTEGER PRIMARY KEY,issuer_id INTEGER,kind TEXT,number INTEGER,payload_json TEXT)');
$db->query('CREATE TABLE tblestimates(id INTEGER PRIMARY KEY,clientid INTEGER,number INTEGER)');
$db->query("INSERT INTO tblestimates VALUES(901,100,1001),(902,200,1002)");
$db->query("INSERT INTO tblitemable VALUES(4,901,'estimate','estimate-line primary',''),(5,902,'estimate','estimate-line B private','')");
$db->query("INSERT INTO tblissuers_resource_permissions VALUES(2,18,'estimates','view'),(3,18,'estimates','view')");
$estimateA=array_values(array_filter($search->search(2,18,'estimate-line'),fn($g)=>$g['type']==='estimate_items'))[0]['result'];
hc(count($estimateA)===1&&$estimateA[0]['secondary_label']==='estimate-line primary','legacy estimate item enforces client boundary before hydration');
hc($search->search(3,18,'estimate-line')===[],'named estimates never inherit primary legacy line items');
$db->query("DELETE FROM tblissuers_resource_permissions WHERE issuer_id=2 AND staff_id=18");hc($search->search(2,18,'needle')===[],'revoked feature no results');
$db->query('UPDATE tblissuers_staff SET can_view=0 WHERE issuer_id=2 AND staff_id=18');try{$search->search(2,18,'needle');throw new LogicException('revoked member searched');}catch(DomainException $e){}
echo "Native search SQLite: same query A/B isolation, wildcard escaping, feature/member revocation passed. Other search families require dedicated fixtures.\n";
